{
    "note_id": "3828ccd0-2424-4ea4-bdfb-abb4da59b405",
    "prompts": [
        {
            "key": "mental_status",
            "prompt": "Evaluate the mental status of the patient based on the session notes. Assess cognitive function, mood, affect, and overall mental state.",
            "modelId": "anthropic.claude-3-haiku-20240307-v1:0",
            "temperature": 0.3
        },
        {
            "key": "suicidality",
            "prompt": "Assess the patient's risk of suicide. Look for warning signs, ideation, plans, or previous attempts mentioned in the session.",
            "modelId": "us.anthropic.claude-3-5-haiku-20241022-v1:0",
            "temperature": 0.3
        },
        {
            "key": "homicidality",
            "prompt": "Evaluate the patient's risk of harm to others. Assess any threats, violent ideation, or dangerous behaviors.",
            "modelId": "anthropic.claude-3-haiku-20240307-v1:0",
            "temperature": 0.3
        },
        {
            "key": "subjective",
            "prompt": "Extract and analyze the subjective information from the session. This includes patient's reported symptoms, feelings, and experiences.",
            "modelId": "anthropic.claude-3-haiku-20240307-v1:0",
            "temperature": 0.3
        },
        {
            "key": "objective",
            "prompt": "Identify and evaluate objective observations from the session. This includes observable behaviors, appearance, and clinical observations.",
            "modelId": "anthropic.claude-3-haiku-20240307-v1:0",
            "temperature": 0.3
        },
        {
            "key": "assessment_therapeutic_intervention",
            "prompt": "Assess the therapeutic interventions used in the session and their effectiveness. Evaluate the therapeutic approach and techniques applied.",
            "modelId": "us.anthropic.claude-3-5-haiku-20241022-v1:0",
            "temperature": 0.3
        },
        {
            "key": "reaction_to_intervention",
            "prompt": "Evaluate the patient's reaction to the therapeutic interventions. Assess engagement, response, and effectiveness of the interventions.",
            "modelId": "anthropic.claude-3-haiku-20240307-v1:0",
            "temperature": 0.3
        },
        {
            "key": "plan_and_collaboration",
            "prompt": "Review the treatment plan and collaboration between therapist and patient. Assess goal setting, planning, and patient involvement.",
            "modelId": "anthropic.claude-3-haiku-20240307-v1:0",
            "temperature": 0.3
        },
        {
            "key": "therapist_reflection",
            "prompt": "Provide therapist reflection on the session. Include clinical insights, concerns, and observations about the therapeutic process.",
            "modelId": "us.anthropic.claude-3-5-haiku-20241022-v1:0",
            "temperature": 0.3
        },
        {
            "key": "progress",
            "prompt": "Evaluate the patient's progress in therapy. Assess improvements, setbacks, and overall therapeutic progress.",
            "modelId": "anthropic.claude-3-haiku-20240307-v1:0",
            "temperature": 0.3
        },
        {
            "key": "aggregator",
            "prompt": "You are a licensed clinical documentation reviewer acting as a FINAL AGGREGATOR.\n\nCombine and summarize all previously evaluated sections and produce a final compliance score.\n- Any section flagged as 'copied from previous note' MUST be a Critical violation (-25 pts).\n- All points_deducted MUST be multiples of 5 only.\n- Start score at 100 and subtract points based strictly on flagged issues.\n- Return pass=true if score > 75.\n- Do NOT introduce new issues or infer content.\n- Report vague or missing info explicitly.\n\nReturn a valid JSON using the keys: score, pass, sentiment, summary, evaluation, issues (array), and individual section evaluations.",
            "modelId": "us.anthropic.claude-haiku-4-5-20251001-v1:0",
            "temperature": 0.4
        }
    ],
    "current_note": "Session Duration: 10am-10:53am\n\nMental Status (optional): \n\nSuicidality: Denied\n\nHomicidality: Not reported\n\nSubjective: The client presented in a anxious manner. Client discussed recent challenges within her relationship. Client was able to express her worries and fears. Client was vocal in the session.\n\nObjective: Client was engaged and interactive during the session.\n\nAssessment & Therapeutic Intervention: Therapist intervened with a person centered approach, engaging in skills such as active listening, empathic responding, and unconditional positive regard. Client was provided with education on somatic exercises she can practice to improve her self regulation.\n\nReaction to Intervention: The client was receptive and interactive throughout the duration of the session and responded well to all interventions provided by the therapist.\n\nPlan and Collaboration: Client to continue to meet for weekly individual session. Client was encouraged to engage in a beginners yoga class.\n\nTherapist Reflection and Insight (optional): \n\nProgress: Progress (Moderate progress.)\n\nTherapist Initials: Raquel Castello, LMHC, R.V.C",
    "prev_note": "Session Duration: 10am-10:53am\n\nMental Status (optional): \n\nSuicidality: Denied\n\nHomicidality: Not reported\n\nSubjective: The client presented in a calm manner. Client discussed recent progress that she has noticed. Client was able to explore triggers to anxiety.\n\nObjective: Client was engaged and interactive during the session.\n\nAssessment & Therapeutic Intervention: Therapist intervened with a person centered approach, engaging in skills such as active listening, empathic responding, and unconditional positive regard. Client was able to explore tools that she can utilize for grounding and self regulation. Writer provided education on dbt mindfulness skills.\n\nReaction to Intervention: Client was receptive to education. Client was provided with workbooks she can look into for further education.\n\nPlan and Collaboration: Client to continue with weekly individual sessions. The client to engage in mindfulness and grounding skills during the week.\n\nTherapist Reflection and Insight (optional): \n\nProgress: Progress (Some progress.)\n\nTherapist Initials: Raquel Castello, LMHC, R.V.C"
}
